-- Issue #733, lot AC (chantier C4) : cinq problèmes de comptage du joueur de club (difficulté 850 à 1050). Thème « Compter » :
-- Noir est devant d’un demi-point (komi 6,5, règle japonaise), un seul coup l’empêche de le perdre ; prisonniers et pierres
-- mortes comptés. 9 × 9, Noir au trait. Problèmes communs (owner_id null), tous prouvés par src/go/lot-ac.test.ts : minimax
-- exact de src/go/refutation-fin.ts, territoires prouvés sûrs par src/go/preuve-vie-mort.ts. Même contenu que
-- src/content/lots/ac-compter.ts. Insertion seule : aucun problème existant n’est touché. setup.refutation : texte
-- affiché après une erreur. La table puzzles garde sa RLS (activée dans 20260926235308_progression_problemes_lecons_badges).
insert into public.puzzles (id, owner_id, size, setup, answers, title, prompt, explanation, difficulty) values
 ('ac01', null, 9, '{"rows":["...XXOO..","...X..O..","..XXOOOOO","XXXOO....","..XOOOOOO","..XXOO...","XXXXXOO..","....XXOOO",".....XXO."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue E8 : F8 devient son territoire, et il gagne."}', array['E8'], 'Le demi-point à défendre', 'Komi : 6,5 points pour Blanc. Compte les deux camps : tu es devant d’un demi-point, mais Blanc peut te le reprendre en un coup. Joue-le avant lui.', 'Bravo ! Tu as 21 points de territoire, Blanc 14 + 6,5 = 20,5 : tu gagnes d’un demi-point. Si Blanc jouait E8, F8 deviendrait son territoire : 15 + 6,5 = 21,5, et il gagnerait. En E8, F8 n’est plus à personne : c’est une dame (point neutre).', 850),
 ('ac02', null, 9, '{"rows":["...OX....","OOOOXX...","...OOX...","..OOXXXXX","..OXXT...","..OOXXXXX","...OXX...","OOOOOX...","..O..X..."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue E1 : D1 devient son territoire, et il gagne. La pierre morte n’a pas besoin d’être prise : elle est retirée au compte."}', array['E1'], 'Un prisonnier de plus', 'Komi : 6,5 points pour Blanc. La pierre blanche marquée est morte : c’est un prisonnier pour toi. Tu es devant d’un demi-point : empêche Blanc de te le reprendre.', 'Bravo ! Tu as 23 points de territoire (la pierre morte comprise, une fois retirée) + 1 prisonnier = 24. Blanc a 17 + 6,5 = 23,5 : tu gagnes d’un demi-point. Si Blanc jouait E1, D1 deviendrait son territoire, et il gagnerait. En E1, D1 n’est plus à personne : c’est une dame (point neutre).', 900),
 ('ac03', null, 9, '{"rows":["...XX....","...XX....","...XX....","..XXXXXXX","XXX.O.OOX","OO.OO.OOO",".OOOOOO..",".O..O.O..","SO..O.O.."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue F5 : F4 devient son territoire, et il gagne. C4 et D5 sont des dames : les remplir ne change rien."}', array['F5'], 'La pierre morte de Noir', 'Komi : 6,5 points pour Blanc. Ta pierre marquée est morte : c’est un prisonnier pour Blanc. Tu es devant d’un demi-point : empêche Blanc de te le reprendre.', 'Bravo ! Tu as 23 points de territoire. Blanc a 15 points de territoire (A1 comprise, une fois ta pierre retirée) + 1 prisonnier + 6,5 = 22,5 : tu gagnes d’un demi-point. Si Blanc jouait F5, F4 deviendrait son territoire, et il gagnerait. C4 et D5 sont des dames (points neutres) : les remplir ne change rien.', 950),
 ('ac04', null, 9, '{"rows":["....XO...","XXXXXOO..","....XXO..","....X.OOO","...XXOO..","XXXX.O...","...XOO...","...XOOOOO","...X..O.."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue E1 : F1 devient son territoire, et il gagne. Remplir une dame ne change rien au compte."}', array['E1'], 'Quel point compte vraiment ?', 'Komi : 6,5 points pour Blanc. Plusieurs points sont encore ouverts, mais un seul change le compte. Tu es devant d’un demi-point : garde-le.', 'Bravo ! E4 et F6 sont des dames (points neutres) : les remplir ne change aucun compte. Le point qui compte est E1. Si Blanc jouait E1, F1 deviendrait son territoire, et il gagnerait. Avec E1, tu as 24 points, Blanc 17 + 6,5 = 23,5 : tu gagnes d’un demi-point.', 1000),
 ('ac05', null, 9, '{"rows":["....XXOS.","XXXXX.OOO","....XOOO.","....XX.O.","XXXXX.OOO","..XXO.O..","T.XOOOOOO","..XXO....","...XO...."],"toPlay":"B","refutation":"Pas tout à fait. Blanc joue F5 : F4 devient son territoire, et il gagne. Les pierres mortes n’ont pas besoin d’être prises : elles sont retirées au compte."}', array['F5'], 'Deux pierres mortes', 'Komi : 6,5 points pour Blanc. Les deux pierres marquées sont mortes, une de chaque couleur. Tu es devant d’un demi-point : garde-le.', 'Bravo ! Tu as 21 points de territoire (A3 comprise, une fois la pierre blanche retirée) + 1 prisonnier = 22. Blanc a 14 points de territoire (H9 comprise, une fois ta pierre retirée) + 1 prisonnier + 6,5 = 21,5 : tu gagnes d’un demi-point. Si Blanc jouait F5, F4 deviendrait son territoire, et il gagnerait. F8 et G6 sont des dames (points neutres).', 1050)
on conflict (id) do nothing;
